  "verdict": {
    "vulnerable": true/false,
    "confidence": 0.0-1.0,
    "cwe": ["CWE-..."],
    "severity": "low|medium|high|critical|unknown",
    "summary": "..."
  },
  "evidence": [
    {
      "file": null,
      "function": null,
